<script lang="ts">import Steps from '@fex-design/svelte/primitive/steps-root';import Button from '@fex-design/svelte/ui/button';import Card from '@fex-design/svelte/ui/card';import StepList from './step-list.svelte';let current=$state<'account'|'profile'|'review'>('account')</script><Card title="Controlled" description="Business completion updates current; navigation requests the same value through onChange."><Steps navigation {current} onchange={(value)=>current=value as typeof current}><StepList/></Steps><Button class="mt-space-md" onclick={()=>current=current==='account'?'profile':'review'}>Complete current task</Button></Card>
